// Pausa manual (recepção assumiu a conversa) + eco do próprio bot.
const vars = $('Variáveis').first().json;
const pausa = $input.first().json;

if (vars.fromMe === true) {
  // Mensagem saiu do número da clínica: alguém da recepção respondeu.
  return [{ json: { ...vars, action: 'PAUSE_MANUAL', reason: 'fromMe' } }];
}

if (pausa && pausa.propertyName) {
  return [{ json: { ...vars, action: 'STOP', reason: 'ia_pausada' } }];
}

return [{ json: { ...vars, action: 'CONTINUE' } }];

// Debounce + dedup atômico: várias mensagens seguidas do paciente viram um
// único turno, e só a execução que ganhou o INCR (==1) segue adiante.
// Fail-open: se não der para ler o claim, processa (duplicar é melhor que emudecer).
const buffer = ($('Redis: Get Buffer').first().json.buffer) || [];

if (!Array.isArray(buffer) || buffer.length === 0) {
  return [{ json: { skip: true, reason: 'empty_buffer' } }];
}

const parsed = buffer.map(b => {
  try { return typeof b === 'string' ? JSON.parse(b) : b; } catch { return null; }
}).filter(Boolean);

if (parsed.length === 0) {
  return [{ json: { skip: true, reason: 'parse_failed' } }];
}

const latest = parsed.reduce((acc, m) => ((m.ts || 0) > (acc.ts || 0) ? m : acc), parsed[0]);

let claimVal = null;
try {
  const cj = $('Redis: Claim Debounce').first().json;
  if (cj && typeof cj === 'object') {
    for (const k of Object.keys(cj)) {
      const v = cj[k];
      if (typeof v === 'number' && isFinite(v)) { claimVal = v; break; }
      if (typeof v === 'string' && /^\d+$/.test(v.trim())) { claimVal = parseInt(v.trim(), 10); break; }
    }
  }
} catch (e) {}

const isWinner = (claimVal === null) ? true : (claimVal === 1);
const vars = $('Variáveis').first().json;

return [{
  json: {
    skip: !isWinner,
    dedup_claim: claimVal,
    dedup_reason: isWinner ? 'winner' : 'duplicate_execution_skipped',
    latestTs: latest.ts || 0,
    listaMensagens: parsed.map(m => m.msg).join('\n').trim(),
    countMsgs: parsed.length,
    tipos: [...new Set(parsed.map(m => m.tipo))],
    mobile: vars.mobile,
    pushName: vars.pushName,
    remoteJid: vars.remoteJid
  }
}];

// Resolve sessionId e monta o contexto do paciente para o agente.
const vars = $('Variáveis').first().json;
const consolidado = $('Consolidar Buffer').first().json;
const paciente = $input.first().json;

const isNew = !paciente || !paciente.telefone;
const sessionId = isNew
  ? 'priore:' + vars.mobile + ':' + Date.now()
  : (paciente.sessionid || ('priore:' + vars.mobile));

return [{
  json: {
    isNewPaciente: isNew,
    sessionId,
    sessionKey: sessionId,
    mobile: vars.mobile,
    pushName: vars.pushName || paciente?.push_name || '',
    nome: paciente?.nome || vars.pushName || '',
    email: paciente?.email || '',
    especialidade_interesse: paciente?.especialidade_interesse || '',
    primeira_vez: paciente?.primeira_vez === false ? false : true,
    convenio_ciente: paciente?.convenio_ciente === true,
    status_atendimento: paciente?.status_atendimento || 'novo',
    estado_funil: paciente?.estado_funil || 'onboarding',
    perfil_resumo: paciente?.perfil_resumo || '',
    listaMensagens: consolidado.listaMensagens,
    tipos: consolidado.tipos,
    countMsgs: consolidado.countMsgs,
    remoteJid: vars.remoteJid,
    qtd_interacoes: (paciente?.qtd_interacoes || 0) + 1,
    // Expostos para o dedup cross-execução no validador
    ultima_resposta_ia: paciente?.ultima_resposta_ia || '',
    ultima_mensagem_paciente: paciente?.ultima_mensagem_paciente || consolidado.listaMensagens || '',
    ultimo_contato: paciente?.ultimo_contato || null
  }
}];

