// Validador Resposta IA — barreira clínica + antialucinação.
// Regra: é melhor pedir um instante ao paciente do que enviar preço,
// diagnóstico ou confirmação inventada.

const TITULOS = ["Estética do sorriso", "Implantes e reabilitação", "Harmonização orofacial", "Periodontia", "Ortodontia", "Odontologia restauradora"];

let resposta = '';
try {
  resposta = ($('Bella — SDR Priore').first().json.output || '').toString();
} catch (e) {
  try { resposta = ($input.first().json.output || '').toString(); } catch (e2) {}
}

const sessao = (() => {
  try { return $('Resolver Sessão').first().json; } catch (e) { return {}; }
})();

const consultaDB = (() => {
  try {
    const row = $('Buscar Consulta Ativa').first().json;
    return (row && row.id && row.status === 'agendada') ? row : null;
  } catch (e) { return null; }
})();

// --- Deduplica bloco de confirmação repetido na mesma resposta -------------
{
  const marks = [...resposta.matchAll(/✅\s*Consulta\s+confirmad/gi)];
  if (marks.length > 1) resposta = resposta.slice(0, marks[1].index).trim();
}

// --- Barreiras clínicas ---------------------------------------------------
const PRECO = /(R\$\s?\d)|(\b\d{2,}\s?(reais|mil)\b)|\b(custa|custam|valor\s+(é|e|fica|gira)|fica\s+em\s+torno|a\s+partir\s+de\s+R?\$?\s?\d|parcel\w*\s+em\s+\d|or[çc]amento\s+(é|e)\s+de)\b/i;
const DIAGNOSTICO = /\b(voc[êe]\s+(est[áa]|tem|possui|apresenta)\s+(um[a]?\s+)?(c[áa]rie|periodontite|gengivite|infec[çc][ãa]o|abscesso|bruxismo|dtm|retra[çc][ãa]o|perda\s+[óo]ssea))|(\bseu\s+caso\s+(é|e)\s+(de|um))|(\bvoc[êe]\s+(vai\s+)?precisa(r)?\s+de\s+(implante|canal|lente|enxerto|aparelho|extra[çc][ãa]o))|(\bo\s+diagn[óo]stico\s+(é|e))|(\bn[ãa]o\s+(é|e)\s+nada\s+grave)|(\bpode\s+ficar\s+tranquil[oa],?\s+(n[ãa]o\s+)?(é|e)\s+)/i;
const PROMESSA = /\b(garant\w+|resultado\s+garantido|sem\s+d[oa]r\s+(nenhuma|alguma|zero)|indolor|100%|cura\s+(definitiva|garantida)|vai\s+ficar\s+perfeit[oa]|para\s+sempre|nunca\s+mais\s+vai)\b/i;
const CLICHE = /(sorriso\s+dos\s+sonhos|sorriso\s+perfeito|transforma[çc][ãa]o\s+do\s+sorriso|antes\s+e\s+depois\s+incr[íi]vel)/gi;

const FALLBACK_PRECO = 'Sobre valores eu não consigo falar por aqui, porque o plano depende do exame clínico. Na avaliação o dentista examina, explica o que está acontecendo e você recebe o plano com os valores por escrito. Quer que eu veja os horários disponíveis?';
const FALLBACK_CLINICO = 'Essa avaliação quem faz é o dentista, presencialmente — por aqui eu não consigo dizer o que você tem nem o que precisa ser feito. Posso ver os horários de avaliação para você?';

let action = 'OK';
let blockedBy = null;

// Clichê é higienizado, não bloqueia a resposta inteira.
if (CLICHE.test(resposta)) {
  resposta = resposta.replace(CLICHE, 'seu sorriso');
  action = 'SANITIZED_CLICHE';
}

if (PRECO.test(resposta)) {
  resposta = FALLBACK_PRECO;
  action = 'BLOCKED_PRECO';
  blockedBy = 'preco';
} else if (DIAGNOSTICO.test(resposta)) {
  resposta = FALLBACK_CLINICO;
  action = 'BLOCKED_DIAGNOSTICO';
  blockedBy = 'diagnostico';
} else if (PROMESSA.test(resposta)) {
  resposta = FALLBACK_CLINICO;
  action = 'BLOCKED_PROMESSA';
  blockedBy = 'promessa';
}

// --- Confirmação / cancelamento -------------------------------------------
const CONFIRMOU = /\b(agendad[ao]|agendei|marcad[ao]|marquei|marcamos|confirmad[ao]|confirmei|reservad[ao]|consulta\s+(est[áa]|foi)\s+(agendad|marcad|confirmad)[ao])\b/i;
const CANCELOU = /\b(cancel\w+|desmarc\w+)\b/i;
const REMARCOU = /\b(remarcad[ao]|remarcamos|reagendad[ao]|nova\s+data)\b/i;

const DATA_COMPLETA = /(\d{1,2})\/(\d{1,2})\/(\d{4})[^\d]{1,30}?(\d{1,2}):(\d{2})/;
const DATA_CURTA = /(\d{1,2})\/(\d{1,2})(?!\/)[^\d]{1,30}?(\d{1,2}):(\d{2})/;

function pad(v) { return String(v).padStart(2, '0'); }
function buildIso(m, anoImplicito) {
  try {
    let dd, mm, yyyy, hh, mi;
    if (anoImplicito) {
      [, dd, mm, hh, mi] = m;
      yyyy = String(new Date().getFullYear());
    } else {
      [, dd, mm, yyyy, hh, mi] = m;
    }
    return yyyy + '-' + pad(mm) + '-' + pad(dd) + 'T' + pad(hh) + ':' + pad(mi) + ':00-03:00';
  } catch (e) { return null; }
}

let dataMatch = resposta.match(DATA_COMPLETA);
let anoImplicito = false;
if (!dataMatch) {
  const curta = resposta.match(DATA_CURTA);
  if (curta) { anoImplicito = true; dataMatch = curta; }
}

const isCancelContext = CANCELOU.test(resposta);
const afirmouConfirmacao = CONFIRMOU.test(resposta) && !isCancelContext;
const dataIso = dataMatch ? buildIso(dataMatch, anoImplicito) : null;

let agendou = false;
let cancelou = false;

if (afirmouConfirmacao) {
  if (dataIso && new Date(dataIso).getTime() > Date.now() - 3600000) {
    agendou = true;
  } else if (consultaDB) {
    // Reafirmou uma consulta que já existe no banco: legítimo, sem novo insert.
    action = action === 'OK' ? 'CONFIRM_EXISTENTE' : action;
  } else {
    // Diz que agendou, sem data válida e sem registro: alucinação.
    resposta = 'Só um instante que eu confirmo sua consulta na agenda aqui.';
    action = 'BLOCKED_CONFIRMACAO_SEM_DATA';
    blockedBy = 'confirmacao_alucinada';
  }
}

if (isCancelContext && consultaDB) cancelou = true;

// --- Especialidade citada na resposta ------------------------------------
let especialidade = sessao.especialidade_interesse || '';
for (const t of TITULOS) {
  if (resposta.toLowerCase().includes(t.toLowerCase())) { especialidade = t; break; }
}

// --- Dedup entre execuções (evita mandar a mesma coisa duas vezes) --------
let duplicate = false;
const anterior = String(sessao.ultima_resposta_ia || '').trim();
if (anterior && anterior === resposta.trim() && action === 'OK') {
  const ultimo = sessao.ultimo_contato ? new Date(sessao.ultimo_contato).getTime() : 0;
  if (ultimo && (Date.now() - ultimo) < 120000) {
    duplicate = true;
    resposta = '';
    action = 'OK_DEDUPED';
  }
}

return [{
  json: {
    output: resposta,
    agendou,
    cancelou,
    remarcou: REMARCOU.test(resposta),
    data_consulta_iso: dataIso,
    especialidade,
    _validation: {
      action,
      blocked_by: blockedBy,
      duplicate_of_previous: duplicate,
      tinha_consulta_no_banco: !!consultaDB,
      afirmou_confirmacao: afirmouConfirmacao
    }
  }
}];

// Invalida o cache de agenda do dia afetado. O TTL curto (300s) já limita a
// janela de defasagem; isso apenas encurta ainda mais depois de escrever na agenda.
const v = $('Validador Resposta IA').first().json;
const iso = v.data_consulta_iso;
const dia = iso ? String(iso).slice(0, 10) : $now.setZone('America/Sao_Paulo').toFormat('yyyy-MM-dd');

return [{
  json: {
    dia,
    cacheKeys: ['AVALIACAO', 'RETORNO', 'URGENCIA'].map(t => `priore:calcache:${dia}_${dia}_${t}`)
  }
}];

// Consolida o que vai para o perfil do paciente. A resposta autoritativa é a do
// validador — o item de entrada pode ter sido substituído pelos nós de backup.
const vars = $('Variáveis').first().json;
const sessao = $('Resolver Sessão').first().json;
const validacao = $('Validador Resposta IA').first().json;

const output = String(validacao.output ?? '').trim();
const agora = new Date().toISOString();

let estado = sessao.estado_funil || 'onboarding';
if (validacao.agendou) estado = 'agendado';
else if (validacao.cancelou) estado = 'cancelado';
else if (sessao.qtd_interacoes > 1 && estado === 'onboarding') estado = 'qualificacao';

return [{
  json: {
    telefone: vars.mobile,
    nome: sessao.nome,
    sessionid: sessao.sessionId,
    push_name: sessao.pushName,
    email: sessao.email,
    especialidade_interesse: validacao.especialidade || sessao.especialidade_interesse || '',
    ultima_mensagem_paciente: sessao.listaMensagens,
    ultima_resposta_ia: output,
    ultimo_contato: agora,
    updated_at: agora,
    qtd_interacoes: sessao.qtd_interacoes,
    estado_funil: estado,
    status_atendimento: validacao.agendou ? 'agendado' : (sessao.status_atendimento || 'ativo'),
    isNew: sessao.isNewPaciente,
    bellaOutput: output
  }
}];

// Rede de segurança contra vazamento de erro do output parser e contra
// bloco de confirmação quebrado em vários segmentos.
const item = $input.first().json;

const ERROS_PARSER = [
  'You must format your output as a JSON value',
  'Voce precisa formatar sua saida',
  'Você precisa formatar sua saída',
  'formatar sua saida como um valor JSON',
  'formatar sua saída como um valor JSON',
  'atenda a um determinado',
  'deve ser seguido corretamente'
];
const SCHEMA_HINT = 'JSON Schema';

function temErroParser(s) {
  if (typeof s !== 'string') return false;
  if (ERROS_PARSER.some(m => s.includes(m))) return true;
  return s.includes(SCHEMA_HINT) && /schema|formatar|format your output/i.test(s);
}

const LINHA_CONFIRMACAO = /^[✅📅🦷📍🕐⏱️]/;
const out = item.output;

// Silêncio intencional (dedup no validador) não deve virar "Desculpe...".
const vazio = !out
  || (typeof out === 'string' && !out.trim())
  || (out && typeof out === 'object' && Array.isArray(out.messages) && out.messages.length === 0);

if (vazio) {
  let dedup = false;
  try {
    const v = $('Validador Resposta IA').first().json._validation;
    dedup = !!(v && (v.duplicate_of_previous === true || String(v.action || '').endsWith('_DEDUPED')));
  } catch (e) {}
  return [{
    json: {
      ...item,
      output: { messages: [] },
      _humanizer: { skipped_empty: true, was_dedup: dedup }
    }
  }];
}

let messages = null;
let motivoFallback = null;

if (out && Array.isArray(out.messages) && out.messages.length > 0) {
  const ruim = out.messages.some(m => typeof m !== 'string' || temErroParser(m)
    || (m.length > 120 && m.includes(SCHEMA_HINT)));
  if (ruim) motivoFallback = 'output.messages contém erro do parser';
  else messages = out.messages.map(m => String(m).trim()).filter(Boolean);
} else if (typeof out === 'string') {
  if (temErroParser(out)) motivoFallback = 'output veio como string de erro do parser';
  else messages = [out.trim()];
} else {
  motivoFallback = 'output sem messages válido';
}

let usouFallback = false;
if (!messages || messages.length === 0) {
  usouFallback = true;
  let original = '';
  try { original = String($('Preparar Persistência').first().json.bellaOutput || '').trim(); } catch (e) {}
  if (!original) original = 'Desculpe, tive um problema técnico agora. Pode repetir, por favor?';
  let segs = original.split(/\n\s*\n+/).map(s => s.trim()).filter(Boolean);
  if (segs.length === 0) segs = [original];
  if (segs.length > 3) segs = [segs[0], segs[1], segs.slice(2).join(' ')];
  messages = segs;
}

// Remove segmentos idênticos consecutivos.
let consolidou = false;
if (messages.length >= 2) {
  const dedup = [messages[0]];
  for (let i = 1; i < messages.length; i++) {
    if (dedup[dedup.length - 1].trim() !== messages[i].trim()) dedup.push(messages[i]);
  }
  if (dedup.length !== messages.length) consolidou = true;
  messages = dedup;
}

// Reagrupa o bloco de confirmação em uma única mensagem.
if (messages.length >= 2) {
  const saida = [];
  let buffer = [];
  let emBloco = false;

  const flush = () => {
    if (!buffer.length) return;
    if (buffer.length >= 2 && emBloco) { saida.push(buffer.join('\n')); consolidou = true; }
    else buffer.forEach(m => saida.push(m));
    buffer = [];
  };

  for (const m of messages) {
    if (LINHA_CONFIRMACAO.test(m)) {
      if (!emBloco && buffer.length) flush();
      emBloco = true;
      buffer.push(m);
    } else if (emBloco) {
      buffer.push(m);
      flush();
      emBloco = false;
    } else {
      flush();
      saida.push(m);
    }
  }
  flush();
  messages = saida;
}

return [{
  json: {
    ...item,
    output: { messages },
    _humanizer: {
      used_fallback: usouFallback,
      fallback_reason: motivoFallback,
      consolidated: consolidou,
      messages_count: messages.length
    }
  }
}];

