parameters.jsCode:
const resp = $input.first().json;
const choices = resp.choices || [];
if (choices.length === 0) return [{ json: { skip: true } }];

let parsed = {};
try {
  parsed = JSON.parse(choices[0].message.content);
} catch (e) {
  parsed = { resumo: choices[0].message.content, topicos: [], especialidade_interesse: '', proximos_passos: '' };
}

const sessao = $('Resolver Sessão').first().json;

return [{
  json: {
    telefone: sessao.mobile,
    resumo: parsed.resumo || '',
    topicos: Array.isArray(parsed.topicos) ? parsed.topicos.join(', ') : (parsed.topicos || ''),
    especialidade_interesse: parsed.especialidade_interesse || sessao.especialidade_interesse || '',
    proximos_passos: parsed.proximos_passos || '',
    status_atendimento_apos: sessao.status_atendimento || 'ativo'
  }
}];

const body = $input.first().json.body || $input.first().json;
const hoje = $now.setZone('America/Sao_Paulo').toFormat('yyyy-MM-dd');

const startDay = body.startDay || hoje;
const endDay = body.endDay || startDay;
const tipo = String(body.tipo || 'AVALIACAO').toUpperCase();
const force = body.force === true || body.force === 'true';

return [{
  json: {
    startDay,
    endDay,
    tipo: ['AVALIACAO', 'RETORNO', 'URGENCIA'].includes(tipo) ? tipo : 'AVALIACAO',
    force,
    cacheKey: `priore:calcache:${startDay}_${endDay}_${tipo}`
  }
}];

// Calcula horários livres da Priore.
// Funcionamento: seg–sex 8h–19h, sáb 9h–13h, domingo fechado.
// Almoço da equipe: 12:00–13:30 nos dias de semana.
const input = $('Cal: Parse Input').first().json;

const eventos = [];
for (const nome of ['Cal: GET Agenda Avaliação', 'Cal: GET Agenda Clínica']) {
  try {
    const j = $(nome).all().map(i => i.json);
    for (const row of j) {
      if (row && (row.start || row.id)) eventos.push(row);
      else if (row && Array.isArray(row.items)) eventos.push(...row.items);
      else if (row && Array.isArray(row.value)) eventos.push(...row.value);
    }
  } catch (e) {}
}

const ocupados = [];
for (const evt of eventos) {
  if (!evt) continue;
  if (evt.status === 'cancelled') continue;
  if (evt.transparency === 'transparent') continue;
  const s = evt.start?.dateTime || evt.start?.date;
  const e = evt.end?.dateTime || evt.end?.date;
  if (!s || !e) continue;
  ocupados.push({ startISO: s, endISO: e, titulo: evt.summary || '(sem título)' });
}

// [horaInicio, minInicio, horaFim, minFim] por tipo e por dia útil/sábado
const CONFIG = {
  AVALIACAO: { min: 60, semana: [[9, 0, 12, 0], [13, 30, 18, 0]], sabado: [[9, 0, 12, 0]] },
  RETORNO:   { min: 45, semana: [[8, 0, 12, 0], [13, 30, 18, 30]], sabado: [[9, 0, 12, 30]] },
  URGENCIA:  { min: 30, semana: [[8, 0, 12, 0], [13, 0, 18, 30]], sabado: [[9, 0, 12, 30]] }
};
const cfg = CONFIG[input.tipo] || CONFIG.AVALIACAO;
const TZ = '-03:00';
const ANTECEDENCIA_MIN_H = 3;
const JANELA_MAX_DIAS = 60;

const FERIADOS = new Set([
  '2026-01-01', '2026-01-25', '2026-02-16', '2026-02-17', '2026-03-29', '2026-04-21',
  '2026-05-01', '2026-06-04', '2026-07-09', '2026-09-07', '2026-10-12', '2026-11-02',
  '2026-11-15', '2026-11-20', '2026-12-25',
  '2027-01-01', '2027-01-25', '2027-02-08', '2027-02-09', '2027-03-26', '2027-04-21',
  '2027-05-01', '2027-05-27', '2027-07-09', '2027-09-07', '2027-10-12', '2027-11-02',
  '2027-11-15', '2027-11-20', '2027-12-25'
]);

const pad = n => String(n).padStart(2, '0');
const toISO = d =>
  d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate()) +
  'T' + pad(d.getHours()) + ':' + pad(d.getMinutes()) + ':00' + TZ;

const agora = Date.now();
const limiteMin = agora + ANTECEDENCIA_MIN_H * 3600 * 1000;
const limiteMax = agora + JANELA_MAX_DIAS * 24 * 3600 * 1000;

const slots_livres = [];
const slots_ocupados = [];
const DIAS = ['domingo', 'segunda', 'terça', 'quarta', 'quinta', 'sexta', 'sábado'];

const dtStart = new Date(input.startDay + 'T00:00:00' + TZ);
const dtEnd = new Date((input.endDay || input.startDay) + 'T23:59:59' + TZ);

for (let d = new Date(dtStart); d <= dtEnd; d.setDate(d.getDate() + 1)) {
  const dateStr = d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate());
  const dow = d.getDay();
  if (dow === 0) continue;                 // domingo fechado
  if (FERIADOS.has(dateStr)) continue;

  const faixas = dow === 6 ? cfg.sabado : cfg.semana;

  for (const [h0, m0, hF, mF] of faixas) {
    let h = h0, m = m0;
    while ((h < hF) || (h === hF && m < mF)) {
      const ini = new Date(d.getFullYear(), d.getMonth(), d.getDate(), h, m, 0);
      const fim = new Date(ini.getTime() + cfg.min * 60000);

      // O slot precisa terminar dentro da faixa.
      const fimFaixa = new Date(d.getFullYear(), d.getMonth(), d.getDate(), hF, mF, 0);
      if (fim > fimFaixa) break;

      const iniISO = toISO(ini);
      const fimISO = toISO(fim);
      const conflito = ocupados.find(o => !(o.endISO <= iniISO || o.startISO >= fimISO));

      const slot = {
        date: dateStr,
        time: pad(h) + ':' + pad(m),
        diaSemana: DIAS[dow],
        startISO: iniISO,
        endISO: fimISO
      };

      const t = ini.getTime();
      if (conflito) slots_ocupados.push({ ...slot, conflito_com: conflito.titulo });
      else if (t >= limiteMin && t <= limiteMax) slots_livres.push(slot);

      m += cfg.min;
      if (m >= 60) { h += Math.floor(m / 60); m = m % 60; }
    }
  }
}

return [{
  json: {
    tipo: input.tipo,
    duracao_min: cfg.min,
    startDay: input.startDay,
    endDay: input.endDay,
    antecedencia_minima_horas: ANTECEDENCIA_MIN_H,
    funcionamento: 'seg-sex 8h-19h · sáb 9h-13h · dom fechado',
    slots_livres,
    total_livres: slots_livres.length,
    total_ocupados: slots_ocupados.length,
    cacheKey: input.cacheKey
  }
}];

